  'meal.tip.postWorkout': 'تناول البروتين خلال 30 دقيقة بعد التمرين',
  'meal.tip.dinner': 'ركز على البروتين الخالي من الدهون والخضار للتعافي',
  'meal.tip.snack': 'حافظ على أجزاء صغيرة — استهدف الحصول على 150-200 سعرة حرارية',
  'meal.empty.noFoods': 'لا توجد أطعمة متاحة لهذا النوع من الوجبة في الوقت الحالي.',
  'meal.showMore': 'عرض المزيد',
